SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admittime, a.dischtime, a.deathtime, a.admission_type, a.admit_provider_id, a.admission_location, a.discharge_location, a.insurance, a.language, a.marital_status, a.race, a.edregtime, a.edouttime, a.hospital_expire_flag, COUNT(a.hadm_id) AS n, MIN(e.value) AS min_complexity_score, MAX(e.value) AS max_complexity_score, AVG(e.value) AS avg_complexity_score, AVG(a.los) AS avg_los, SUM(CASE WHEN a.deathtime IS NOT NULL THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(a.hadm_id), 0) AS mortality_%, COUNT(CASE WHEN a.dischtime - a.admittime <= 30 THEN a.hadm_id END) * 100.0 / NULLIF(COUNT(a.hadm_id), 0) AS readmission_30d FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN emar e ON a.hadm_id = e.hadm_id WHERE p.gender = 'M' AND p.anchor_age BETWEEN 58 AND 68 AND a.admission_type = 'COPD exacerbation' AND a.admittime <= CURRENT_DATE - INTERVAL '72 hours' GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admittime, a.dischtime, a.deathtime, a.admission_type, a.admit_provider_id, a.admission_location, a.discharge_location, a.insurance, a.language, a.marital_status, a.race, a.edregtime, a.edouttime, a.hospital_expire_flag ORDER BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admittime, a.dischtime, a.deathtime, a.admission_type, a.admit_provider_id, a.admission_location, a.discharge_location, a.insurance, a.language, a.marital_status, a.race, a.edregtime, a.edouttime, a.hospital_expire_flag NULLS LAST;